head.script:
scwin.checkDataSel = function() {
    var arr = select1.itemArr,
        bool1,
        bool2;
    (arr.length) ? bool1 = true: bool1 = false;
    (arr[0].label == 'label_test1' && arr[1].label == 'label_test2') ?
    bool2 = true: bool2 = false;
    return bool1 && bool2;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('select1').getText() != ''", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkDataSel()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    window.comUtil = {};
    comUtil.setLinkedDataList = function(filterCond) {
        for (window.i = 0; i < filterCond.length; i++) {
            window.contVal = filterCond[i].substring(9);
            console.log("=====>" + contVal);
            window.ldtCodeOption1 = {
                "id": filterCond[i],
                "type": "linkedDataList",
                "option": {
                    "valueAttribute": "",
                    "bind": "dlt_code",
                    "filterCondition": "cls_cd == '" + contVal + "'",
                    "sortCondition": ""
                }
            };
            $p.data.create(ldtCodeOption1);
        }
    };
    //dataList set
    window.jsonData = [{
            "cls_cd": "O0003",
            "detl_cd": "test1",
            "detl_cd_nm": "label_test1"
        },
        {
            "cls_cd": "O0003",
            "detl_cd": "test2",
            "detl_cd_nm": "label_test2"
        },
        {
            "cls_cd": "O0004",
            "detl_cd": "test4",
            "detl_cd_nm": "label_test4"
        }
    ]
    dlt_code.setJSON(jsonData);
    //linkedDataList create
    window.filterCond = [
        "ldt_code_O0003"
    ];
    comUtil.setLinkedDataList(filterCond);
    window.temp = [{
            "col1": "a1",
            "col2": "",
            "col3": "a1"
        },
        {
            "col1": "a1",
            "col2": "a1",
            "col3": "a1"
        },
        {
            "col1": "a1",
            "col2": "a1",
            "col3": "a1"
        }
    ];
    dataList2.setJSON(temp);
    //Function unitTest
    //Created By: Sang.do
    //Created By: 30-Jan-2018
    //end unitTest
}
